from lib import *
S = SS('c9')
steps = [
    step("每次都重新执行 apk add curl(用 ARG BUST 强制该层重做)。没有缓存挂载:BUST=1/2/3 的构建用时 181917 / 98042 / 195787 ms(都要从 Alpine 镜像站下载,这台机器的网络较慢,波动也大)。RUN --mount=type=cache,target=/var/cache/apk:BUST=1 进入时缓存目录里有 0 个文件,用时 193675 ms,结束时缓存目录里有 13 个文件、共 4644 KB;BUST=2 进入时就有 13 个文件,构建只要 943 ms;BUST=3 764 ms。", t=tl(S(1)), mark=lidx(S(1), '没有缓存挂载] BUST=1', '没有缓存挂载] BUST=3'), done=lidx(S(1), 'BUST=2:退出码 0,构建用时 943', 'BUST=3:退出码 0,构建用时 764', '进入时缓存目录里有 13 个文件'), b=bars([['无缓存挂载:BUST=3 (秒)', 195.8, '195.8'], ['缓存挂载:首次(缓存为空)', 193.7, '193.7'], ['缓存挂载:BUST=2', 0.943, '0.94'], ['缓存挂载:BUST=3', 0.764, '0.76']], 195.8, mark=[0, 1], done=[2, 3]), kv=KV([['首次构建', '缓存为空,照样要下载(约 194 秒)'], ['之后每次', '缓存目录里已有 13 个文件,0.8–0.9 秒'], ['注意', '网络慢是这台机器的情况,比例才有参考价值']], ['之后每次'])),
    step("缓存挂载里的东西不会进入镜像:从有缓存挂载的镜像启动后,ls /var/cache/apk | wc -l 是 0(目录里没有文件)。两个镜像的 Size:没有缓存挂载 27.63 MB;有缓存挂载 23.00 MB。(没有缓存挂载的那个反而大 4.63 MB,我没有查原因。)", t=tl(S(2)), mark=lidx(S(2), '= 0', '27.63'), kv=KV([['缓存挂载的内容', '不在镜像里'], ['Size', '23.00 MB 对 27.63 MB(原因未查)']], ['缓存挂载的内容'])),
    step("缓存按 id 区分:同一个 Dockerfile 里两个缓存挂载,id=one 与 id=two。第 1 次构建:id=one 里有 0 个文件,id=two 里有 0 个;第 1 次往 id=one 里写入一个文件;第 2 次构建:id=one 里有 1 个文件,id=two 里仍是 0 个。不同 id 是互不相干的空目录。", t=tl(S(3)), mark=lidx(S(3), '第 2 次构建'), done=lidx(S(3), '第 1 次构建'), kv=KV([['id=one', '第 2 次构建时看到第 1 次写入的文件'], ['id=two', '始终为空,和 one 互相独立']], ['id=two'])),
]
A = mkartc('c9', 9, 'Docker,BuildKit,缓存挂载,构建缓存,apk,真实验证,动画演示',
    '在 Docker Engine 29.8.2(BuildKit)里实测缓存挂载:apk add curl 不带缓存挂载时每次构建 98–196 秒(这台机器网络很慢),带 RUN --mount=type=cache 后第一次要 193.7 秒,之后每次只要 0.76–0.94 秒;缓存里的 13 个文件(4644 KB)不进镜像;不同 id 是互相独立的缓存。',
    '“改了一行 Dockerfile,整个 apt/apk 安装又重新下载一遍”是构建慢的常见原因。RUN --mount=type=cache 让包管理器的缓存目录跨构建保留。这篇用 apk 实测:第一次、之后每次各要多久,缓存里的东西会不会进镜像,以及缓存怎么按 id 区分。',
    [('193.7 秒 → 0.94 秒', '带缓存挂载的 apk add:缓存为空的第一次与缓存已有 13 个文件之后的构建用时'), ('13 个文件 / 4644 KB', 'apk 缓存目录里累积的内容,不会出现在镜像里'), ('id', '不同 id 的缓存互相独立,同一个 id 在多次构建间保留')],
    [('第一次不会更快', '<p>缓存挂载不是魔法:缓存为空的那一次构建要照常下载(193.7 秒,这台机器的网络很慢)。之后每次进入这一步时目录里已经有 13 个文件,同一条 <code>apk add</code> 只要 0.94 秒。没有缓存挂载时即使 Dockerfile 只改了一个无关的 ARG 导致这一层重做,每次也要重新下载(98–196 秒)。</p>'),
     ('不进镜像', '<p>缓存目录只在构建那一步里挂载,构建结束就不在镜像里了:从镜像启动后 <code>/var/cache/apk</code> 是空的。所以缓存不会让镜像变大——也就不需要在 RUN 末尾再 <code>rm -rf</code> 缓存。</p>'),
     ('按 id 区分', '<p>同一个 id 的缓存在构建之间持续累积(第二次构建能看到第一次写进去的文件),不同 id 互不影响。本文每次都显式写了 <code>id</code>;不写时的默认规则我没有测。缓存数据在构建器所在的机器上,CI 里如何持久化,本文没有测。</p>')],
    steps,
    [ENV_C + '。包管理器用 apk(容器能访问 Alpine 镜像站,但这台机器的网络较慢,各次下载用时波动很大,绝对时间只代表本次);每次运行用带时间戳的 id 与 salt 层,保证缓存从空开始;“强制该层重做”用 ARG BUST 的值变化;实验后已删除镜像(BuildKit 里的缓存挂载数据没有手动清理)',
     '没有验证:apt 与 pip / npm 等包管理器的缓存挂载写法、sharing=locked / private 在并发构建下的行为、缓存挂载在 CI 里的持久化、缓存被 BuildKit 垃圾回收的策略、没缓存挂载的镜像比有缓存挂载的镜像大 4.63 MB 的原因'],
    'BuildKit 缓存挂载')
